INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist jedes Projekt nach DIN 69901 relativ innovativ?', 2, '[{"text": "Ja", "correct": true, "because": "Innovation ist ein Merkmal"}, {"text": "Nein", "correct": false, "because": "Kann auch Routine sein"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Merkmal beschreibt "relativ innovativ" am besten?', 3, '[{"text": "Neue Ansätze oder Methoden", "correct": true, "because": "Innovation betrifft Neuerungen"}, {"text": "Wiederholung bekannter Prozesse", "correct": false, "because": "Nicht innovativ"}, {"text": "Feste Zeitplanung", "correct": false, "because": "Unabhängig von Innovation"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Relativ innovativ bedeutet völlig neu. b) Es kann bekannte Elemente enthalten.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Relativ heißt nicht absolut neu"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist zu absolut"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "b) ist korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte machen ein Projekt relativ innovativ?', 4, '[{"text": "Neue Technologien", "correct": true, "because": "Fördern Innovation"}, {"text": "Standardprozesse", "correct": false, "because": "Wenig innovativ"}, {"text": "Unbekannte Herausforderungen", "correct": true, "because": "Erfordern neue Lösungen"}, {"text": "Feste Budgets", "correct": false, "because": "Unabhängig von Innovation"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Projekt ohne neue Technologien relativ innovativ sein?', 2, '[{"text": "Ja", "correct": true, "because": "Neue Prozesse reichen aus"}, {"text": "Nein", "correct": false, "because": "Technologie ist nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist kein Beispiel für relative Innovation?', 3, '[{"text": "Einführung einer neuen Software", "correct": false, "because": "Ist innovativ"}, {"text": "Wiederholung eines alten Projekts", "correct": true, "because": "Fehlt Neuerung"}, {"text": "Neuer Ansatz im Team", "correct": false, "because": "Ist innovativ"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist relative Innovation immer mit hohen Kosten verbunden?', 2, '[{"text": "Nein", "correct": true, "because": "Kosten hängen vom Projekt ab"}, {"text": "Ja", "correct": false, "because": "Innovation kann günstig sein"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Faktor fördert relative Innovation?', 3, '[{"text": "Kreative Problemlösung", "correct": true, "because": "Neue Ideen entstehen"}, {"text": "Strikte Vorgaben", "correct": false, "because": "Begrenzt Innovation"}, {"text": "Wiederholte Abläufe", "correct": false, "because": "Wenig Neuerung"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Innovation muss radikal sein. b) Relativ innovativ erfordert Anpassung.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Relativ erlaubt Anpassung"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "b) trifft zu"}]'),
('00000000-0000-0000-0000-000000000000', 'Was gehört nicht zur relativen Innovation?', 2, '[{"text": "Kopieren eines bestehenden Projekts", "correct": true, "because": "Fehlt Neuerung"}, {"text": "Neue Projektstruktur", "correct": false, "because": "Ist innovativ"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Projekt mit bekannten Tools relativ innovativ sein?', 2, '[{"text": "Ja", "correct": true, "because": "Neue Nutzung ist möglich"}, {"text": "Nein", "correct": false, "because": "Tools allein entscheiden nicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Beispiel zeigt relative Innovation?', 3, '[{"text": "Optimierung eines Prozesses", "correct": true, "because": "Neuer Ansatz"}, {"text": "Identisches Vorgehen wie zuvor", "correct": false, "because": "Keine Neuerung"}, {"text": "Feste Deadlines", "correct": false, "because": "Unabhängig davon"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist relative Innovation dasselbe wie technische Neuheit?', 2, '[{"text": "Nein", "correct": true, "because": "Innovation kann organisatorisch sein"}, {"text": "Ja", "correct": false, "because": "Technik ist nur ein Teil"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente können relativ innovativ sein?', 4, '[{"text": "Neue Methoden", "correct": true, "because": "Fördern Innovation"}, {"text": "Routinetätigkeiten", "correct": false, "because": "Wenig Neuerung"}, {"text": "Kombination bekannter Ansätze", "correct": true, "because": "Neue Anwendung"}, {"text": "Feste Strukturen", "correct": false, "because": "Begrenzen Innovation"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss relative Innovation immer sichtbar sein?', 2, '[{"text": "Nein", "correct": true, "because": "Kann intern liegen"}, {"text": "Ja", "correct": false, "because": "Wirkung zählt mehr"}]'),
('00000000-0000-0000-0000-000000000000', 'Was widerspricht dem Merkmal "relativ innovativ"?', 3, '[{"text": "Exakte Kopie eines Projekts", "correct": true, "because": "Keine Neuerung"}, {"text": "Neue Teamzusammenstellung", "correct": false, "because": "Kann innovativ sein"}, {"text": "Pilotprojekt", "correct": false, "because": "Oft innovativ"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein kleines Projekt relativ innovativ sein?', 2, '[{"text": "Ja", "correct": true, "because": "Größe ist irrelevant"}, {"text": "Nein", "correct": false, "because": "Innovation hängt nicht von Größe ab"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Ansatz unterstützt relative Innovation?', 3, '[{"text": "Experimentelle Vorgehensweise", "correct": true, "because": "Fördert Neues"}, {"text": "Strikte Vorgaben ohne Flexibilität", "correct": false, "because": "Hemmt Innovation"}, {"text": "Wiederholung alter Pläne", "correct": false, "because": "Keine Neuerung"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Relative Innovation erfordert neue Ideen. b) Sie schließt bekannte Methoden aus.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Bekannte Methoden sind erlaubt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) trifft zu"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Ziel von relativer Innovation?', 3, '[{"text": "Verbesserung bestehender Prozesse", "correct": true, "because": "Neuer Ansatz"}, {"text": "Exakte Wiederholung", "correct": false, "because": "Keine Innovation"}, {"text": "Reduktion aller Risiken", "correct": false, "because": "Unabhängig davon"}]');